CREATE FUNCTION pg_temp.assert_true(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; END $$;
INSERT INTO organizations(id,whatsapp_enabled,whatsapp_audio_enabled,whatsapp_sandbox_enabled,whatsapp_sandbox_audio_enabled) VALUES('11111111-1111-4111-8111-111111111111',true,true,true,true);
INSERT INTO auth.users(id) VALUES('33333333-3333-4333-8333-333333333333');
INSERT INTO organization_members(user_id,organization_id) VALUES('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111');
INSERT INTO sales_price_lists(id,organization_id) VALUES('44444444-4444-4444-8444-444444444444','11111111-1111-4111-8111-111111111111');
INSERT INTO whatsapp_integrations(id,organization_id,phone_number_id,status,sales_price_list_id,responsible_user_id) VALUES('55555555-5555-4555-8555-555555555555','11111111-1111-4111-8111-111111111111','123456','ACTIVE','44444444-4444-4444-8444-444444444444','33333333-3333-4333-8333-333333333333');
SELECT * FROM ingest_whatsapp_inbound_message('123456','5491100000000','audio-first','AUDIO',null,'{"audio":{"id":"456"}}');
SELECT * FROM ingest_whatsapp_inbound_message('123456','5491100000000','audio-first','AUDIO',null,'{"audio":{"id":"456"}}');
SELECT * FROM ingest_whatsapp_inbound_message('123456','5491100000000','text-following','TEXT','Quiero dos kilos','{}');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM whatsapp_messages),'Webhook deduplicates audio');
SELECT pg_temp.assert_true((SELECT count(*)=3 FROM agent_jobs),'One transcription and two commercial jobs');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM claim_whatsapp_job_v2('commercial-a','PROCESS_CONVERSATION')),'Text must wait for preceding audio');
CREATE TABLE claimed_audio AS SELECT * FROM claim_whatsapp_job_v2('transcription-a','TRANSCRIBE_AUDIO');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM claimed_audio),'Audio worker claims transcription');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM claim_whatsapp_job_v2('transcription-b','TRANSCRIBE_AUDIO')),'Second worker cannot claim same audio');
SELECT pg_temp.assert_true(NOT complete_whatsapp_transcription((SELECT id FROM claimed_audio),gen_random_uuid(),'incorrecto','test'),'Wrong lease rejected');
SELECT pg_temp.assert_true(reserve_whatsapp_audio_usage((SELECT id FROM claimed_audio),(SELECT lease_token FROM claimed_audio),10),'Reserve quota');
SELECT pg_temp.assert_true(reserve_whatsapp_audio_usage((SELECT id FROM claimed_audio),(SELECT lease_token FROM claimed_audio),10),'Reservation is idempotent');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM whatsapp_processing_usage),'Quota not double counted');
SELECT pg_temp.assert_true(complete_whatsapp_transcription((SELECT id FROM claimed_audio),(SELECT lease_token FROM claimed_audio),'Quiero queso Cremac','test'),'Save transcript');
SELECT pg_temp.assert_true(finish_whatsapp_job_v2((SELECT id FROM claimed_audio),(SELECT lease_token FROM claimed_audio),true),'Finish transcription');
CREATE TABLE claimed_commercial AS SELECT * FROM claim_whatsapp_job_v2('commercial-a','PROCESS_CONVERSATION');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM claimed_commercial),'Commercial becomes eligible');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM claim_whatsapp_job_v2('commercial-b','PROCESS_CONVERSATION')),'One conversation cannot process in parallel');
SELECT * FROM ingest_whatsapp_inbound_message('123456','5491199999999','another-conversation','TEXT','Hola','{}');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM claim_whatsapp_job_v2('commercial-b','PROCESS_CONVERSATION')),'Different conversation processes concurrently');
UPDATE agent_jobs SET lease_expires_at=now()-interval '1 second' WHERE id=(SELECT id FROM claimed_commercial);
SELECT pg_temp.assert_true(NOT renew_whatsapp_job_lease((SELECT id FROM claimed_commercial),(SELECT lease_token FROM claimed_commercial)),'Expired lease cannot revive');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM claim_whatsapp_job_v2('commercial-recovery','PROCESS_CONVERSATION', 'DAEMON',(SELECT id FROM claimed_commercial))),'Expired work can be recovered');
SELECT pg_temp.assert_true(NOT finish_whatsapp_job_v2((SELECT id FROM claimed_commercial),(SELECT lease_token FROM claimed_commercial),true),'Stale worker cannot finish recovered work');
SELECT pg_temp.assert_true((SELECT content='Quiero queso Cremac' FROM whatsapp_messages WHERE external_message_id='audio-first'),'Audio content persists despite following text');
SELECT pg_temp.assert_true(NOT (SELECT public FROM storage.buckets WHERE id='whatsapp-audio'),'Audio bucket is private');
SELECT 'Audio pipeline database checks passed';
